const { api, product, abg } = caller.runtime;
const ids = product.NATIVE_WORKSPACE_WORK_IDS;
const environment = caller.refresh();
const context = await product.observeWorksiteContext({
  workspaceAuthorityBasis: environment.workspaceAuthorityBasis,
  workspaceBinding: environment.workspaceBinding,
  readRoots, maxFiles, maxBytes
});
// Require context.kind === 'worksite_context_observation'; retain exact observation.
