  selection: { memberKey: 'start',
    target: { kind: 'declared_start', startRef: ids.startRef },
    rootMode: 'direct', fhMode: 'direct' },
  programRef: ids.programRef,
  catalog: caller.state.catalog, catalogView: caller.state.catalogView,
  applications: [], admittedInstalls: environment.productInstalls,
  workspaceBinding: environment.workspaceBinding,
  verifyInstallAdmission: install =>
    abg.hasAdmittedProductInstall(environment.artifactTruth, install),
  actorRef: caller.actorRef,
  input: { factory: ({ workspaceBinding, grants }) => {
    // Existing owner issues exactly one invoke grant (run_invocation_operation.js).
    // Assert one grant and its actor/operation/binding joins; do not construct one.
    if (grants.length !== 1) throw new Error('unexpected owner grant count');
    return product.constructNativeWorkspaceWorkTask({
      workspaceAuthorityBasis: environment.workspaceAuthorityBasis,
      workspaceBinding, capabilityGrant: grants[0], context,
      outcome, instructions, readFirst, writeRoots, checks
      // assessment is absent: this is author work.
    });
  } },
  inputValueRef: rootBoundFreshInputValueRef,
  source: { kind: 'none' },
  eventResource: caller.reopen(),
  envelope: {
    definitionContractCoordinates: caller.native.verified.definitionContractCoordinates,
    requestRef: rootBoundFreshRequestRef,
    correlationRef: rootBoundFreshCorrelationRef,
    eventTime: new Date().toISOString(), provenanceRefs: rootControlRefs
  }
});
